def H(t):return f'<h2>{t}</h2>'
def Pp(t):return f'<p>{t}</p>'
def UL(items):return '<ul>'+''.join(f'<li>{i}</li>' for i in items)+'</ul>'
def OL(items):return '<ol>'+''.join(f'<li>{i}</li>' for i in items)+'</ol>'
def TAB(rows,head):return '<table><tr>'+''.join(f'<th>{h}</th>' for h in head)+'</tr>'+''.join('<tr>'+''.join(f'<td>{c}</td>' for c in r)+'</tr>' for r in rows)+'</table>'
def LN(d,c='ln'):return f'<path d="{d}" class="{c}"/>'
def R(x,y,w,h,c='bx',r=3):return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{r}" class="{c}"/>'

# ---------- synthetic signal for hysteresis demo (recomputed) ----------
N=60
sig=[78+3.5*t/N+1.6*math.sin(t*0.9) for t in range(N+1)]
def run(on,off):
    st=False;ints=[];start=None;changes=0
    for t,v in enumerate(sig):
        if not st and v>=on:st=True;start=t;changes+=1
        elif st and v<off:st=False;ints.append((start,t));changes+=1
    if st:ints.append((start,N))
    return ints,changes
single,ch1=run(80,80);hyst,ch2=run(80,77)
n1=sum(1 for _ in single);n2=len(hyst)
assert n1>=4 and n2==1,(n1,n2,single,hyst)
assert 300-250==50

